class Excel {
    private int[][] values;
    private Map<String, List<String>> formulas = new HashMap<>();

    public Excel(int height, char width) {
        values = new int[height + 1][width - 'A' + 1];
    }

    public void set(int row, char column, int val) {
        String key = key(row, column);
        formulas.remove(key);
        values[row][column - 'A'] = val;
    }

    public int get(int row, char column) {
        String key = key(row, column);
        if (!formulas.containsKey(key)) return values[row][column - 'A'];
        int total = 0;
        for (String ref : formulas.get(key)) total += valueOf(ref);
        values[row][column - 'A'] = total;
        return total;
    }

    public int sum(int row, char column, String[] numbers) {
        formulas.put(key(row, column), Arrays.asList(numbers));
        return get(row, column);
    }

    private int valueOf(String ref) {
        if (!ref.contains(":")) return get(Integer.parseInt(ref.substring(1)), ref.charAt(0));
        String[] parts = ref.split(":");
        int r1 = Integer.parseInt(parts[0].substring(1)), r2 = Integer.parseInt(parts[1].substring(1));
        char c1 = parts[0].charAt(0), c2 = parts[1].charAt(0);
        int total = 0;
        for (int r = r1; r <= r2; r++) for (char c = c1; c <= c2; c++) total += get(r, c);
        return total;
    }

    private String key(int row, char col) { return row + "#" + col; }
}
